import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookDiscardIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void discarding_an_available_book_returns_200_with_discarded_status() throws Exception {
        String bookId = registerBook("Lost Atlas");

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("Lost Atlas"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_a_book_on_loan_returns_409_with_book_on_loan_error() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Damaged Atlas");
        loanBook(bookId, memberId);

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));
    }

    @Test
    void loaning_a_discarded_book_returns_409_with_book_discarded_error() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Worn Atlas");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void discarding_an_already_discarded_book_keeps_it_discarded() throws Exception {
        String bookId = registerBook("Twice Atlas");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/{id}/discard", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void book_becomes_loanable_again_after_return_and_can_then_be_discarded() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Returned Atlas");
        String loanId = loanBookAndGetLoanId(bookId, memberId);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new TitleBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"박도윤\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private void loanBook(String bookId, String memberId) throws Exception {
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId)))
                .andExpect(status().isCreated());
    }

    private String loanBookAndGetLoanId(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    record TitleBody(String title) {
    }

    record LoanBody(String bookId, String memberId) {
    }
}

